def resolve(opus, manifest_dir):
    out = {}
    for k, d in opus.items():
        manifest = [int(l.split("\t")[0]) for l in open(HERE / manifest_dir / f"batch_{k}.txt")]
        gset = set(manifest)
        if all(int(key) in gset for key in d):
            for key, lab in d.items(): out[int(key)] = lab
        else:
            for key, lab in d.items(): out[manifest[int(key) - 1]] = lab
    return out

opus_label = {}
opus_label.update(resolve(OPUS1, "review"))     # conf<0.5
opus_label.update(resolve(OPUS2, "review2"))    # 0.5<=conf<0.7
print("opus-reviewed frames:", len(opus_label))

records, n_opus = [], 0
for i, r in enumerate(ROWS):
    img = HERE / "dl" / f"{i}.jpg"
    if not img.exists() or img.stat().st_size == 0: continue
    if i in opus_label:
        lab, src, n_opus = opus_label[i], "opus_review", n_opus + 1
    else:
        lab, src = r["shot"], "v2_highconf"
    if lab not in CLASSES: continue
    records.append({"image": str(img), "label": lab, "annotator": "ai", "source": src,
                    "confidence": r["conf"], "movie": r["movie"]})
print(f"silver records {len(records)} (opus {n_opus}, v2 {len(records)-n_opus})")

silver = datasets.Dataset.from_list(records)
silver = silver.cast_column("image", datasets.Image()).cast_column("label", datasets.ClassLabel(names=CLASSES))

gold = load_dataset("szymonrucinski/types-of-film-shots", split="train")
N = len(gold)
gold = (gold.add_column("annotator", ["human"] * N).add_column("source", ["human"] * N)
            .add_column("confidence", [1.0] * N).add_column("movie", [""] * N))
cols = ["image", "label", "annotator", "source", "confidence", "movie"]
combined = concatenate_datasets([gold.select_columns(cols), silver.select_columns(cols)])
from collections import Counter
print("combined", len(combined), dict(Counter(combined["annotator"])))
combined.push_to_hub("szymonrucinski/types-of-film-shots", private=False)
print("pushed combined -> szymonrucinski/types-of-film-shots")
